UPDATE generation_task_handoff
SET state = 'RETRY',
    next_attempt_at = DATE_ADD(NOW(3), INTERVAL #{delaySeconds} SECOND),
    claim_owner = NULL, lease_until = NULL, last_error = #{error}
WHERE id = #{id} AND state = #{state}

UPDATE generation_task_handoff
SET claim_owner = NULL, lease_until = NULL
WHERE id = #{id} AND state = 'CLAIMED' AND generation = #{generation}
